// The taskbar of a desktop from 1998, below the scene it wraps. Start opens the
// scene list, the task button is the scene that is open, held in while it has the
// focus, the gear opens its settings, and the tray (signal, battery, clock) opens
// the frame's. The window around the scene is optional. Built-in scenes are drawn
// inside it too: while one shows, its own button is held in and the task button
// comes back out and takes you back to the scene.
//
// On a frame that runs its scenes side by side (a Raspberry Pi: app.frame.scenes
// is there), it is a desktop: every scene opened is a window, and they all run at
// once. The scene with the focus is the frame's own (the <yield />), the others
// are <Scene>s. Drag a title bar to move a window and an edge to size it, double
// click it (or its middle button) to fill the desktop, and F11 or Start's "Full
// screen" gives the panel to the window in front; Escape or the pointer at the
// bottom edge brings the taskbar back. Start lists the frame's scenes, the
// taskbar the windows open.
const pad = (n) => String(n).padStart(2, '0')
const on = (value) => value === true || value === 'true'

// Sizes are pixels, of a desktop's size, twice that on a panel with a short side
// of 1000 px or more, whose pixels are small, and in proportion on one under 480,
// which has no room for them. The frame's render scale multiplies on top, which a
// size given as a share of the panel could not do.
let zoom = 1
let edge = 1 // the bevels' width
const px = (n) => `${Math.round(n * zoom * 10) / 10}px`

function clock(now, twentyFour) {
  const minutes = pad(now.getMinutes())
  if (twentyFour) return `${pad(now.getHours())}:${minutes}`
  return `${now.getHours() % 12 || 12}:${minutes} ${now.getHours() < 12 ? 'AM' : 'PM'}`
}

// A box has one border color, so a bevel is three boxes inside each other.
// Pressed, the three boxes swap their light and dark edges: the button goes in.
const Raised = ({ className = '', onClick, children }) => (
  <div className={`flex bg-[#c0c0c0] active:bg-[#909090] border-t-${edge} border-l-${edge} border-white active:border-black ${className}`} onClick={onClick}>
    <div className={`flex flex-1 min-w-0 border-b-${edge} border-r-${edge} border-black active:border-white`}>
      <div className={`flex flex-1 min-w-0 items-center gap-[${px(5)}] px-[${px(6)}] border-b-${edge} border-r-${edge} border-[#808080] active:border-[#dfdfdf]`}>
        {children}
      </div>
    </div>
  </div>
)

const Sunken = ({ className = '', onClick, children }) => (
  <div className={`flex border-t-${edge} border-l-${edge} border-[#808080] active:border-black ${className}`} onClick={onClick}>
    <div className={`flex flex-1 min-w-0 border-b-${edge} border-r-${edge} border-white`}>
      <div className={`flex flex-1 min-w-0 items-center gap-[${px(6)}] px-[${px(6)}]`}>{children}</div>
    </div>
  </div>
)

// A button that stays in while what it stands for is open.
const Toggle = ({ pressed, className = '', onClick, children }) =>
  pressed ? (
    <Sunken className={`bg-[#e4e4e4] active:bg-[#909090] ${className}`} onClick={onClick}>
      {children}
    </Sunken>
  ) : (
    <Raised className={className} onClick={onClick}>
      {children}
    </Raised>
  )

const Logo = () => (
  <svg viewBox="0 0 46 54" className={`w-[${px(20)}] h-[${px(23)}]`}>
    <path fill="#111418" d="M0 0H46V5H5V30H0ZM26 49H41V32H46V54H26Z" />
    <rect x="7" y="36" width="12" height="11" rx="1.4" fill="#1c7c66" />
    <rect x="20" y="24" width="12" height="11" rx="1.4" fill="#8baa3a" />
    <rect x="33" y="12" width="12.5" height="11.5" rx="1.4" fill="#c8a247" />
  </svg>
)

const WindowIcon = () => (
  <svg viewBox="0 0 16 16" className={`w-[${px(16)}] h-[${px(16)}]`}>
    <rect x="0.5" y="1.5" width="15" height="13" fill="#ffffff" stroke="#000000" />
    <rect x="1" y="2" width="14" height="3" fill="#000080" />
  </svg>
)

const Gear = () => (
  <svg viewBox="0 0 48 48" className={`w-[${px(18)}] h-[${px(18)}]`}>
    <path
      fill="#404040"
      d="M20 9L21 3L27 3L28 9L32 11L36 7L41 12L37 16L39 20L45 21L45 27L39 28L37 32L41 36L36 41L32 37L28 39L27 45L21 45L20 39L16 37L12 41L7 36L11 32L9 28L3 27L3 21L9 20L11 16L7 12L12 7L16 11ZM17 24a7 7 0 1 0 14 0a7 7 0 1 0 -14 0Z"
    />
  </svg>
)

// The title bar's two small buttons.
const TitleButton = ({ onClick, children }) => (
  <div className={`flex bg-[#c0c0c0] active:bg-[#909090] border-t-${edge} border-l-${edge} border-white active:border-black`} onClick={onClick}>
    <div className={`flex border-b-${edge} border-r-${edge} border-black active:border-white`}>
      <div className={`flex items-center justify-center w-[${px(20)}] h-[${px(16)}] border-b-${edge} border-r-${edge} border-[#808080] active:border-[#dfdfdf]`}>
        {children}
      </div>
    </div>
  </div>
)

const MaximizeGlyph = () => (
  <svg viewBox="0 0 10 10" className={`w-[${px(9)}] h-[${px(9)}]`}>
    <rect x="0.5" y="0.5" width="9" height="9" fill="none" stroke="#000000" />
    <rect x="0" y="0" width="10" height="2.4" fill="#000000" />
  </svg>
)

// Two windows, one behind the other: the window is maximized, and this sizes it back.
const RestoreGlyph = () => (
  <svg viewBox="0 0 10 10" className={`w-[${px(9)}] h-[${px(9)}]`}>
    <path fill="none" stroke="#000000" d="M2.5 2.5V0.5H9.5V6.5H7.5" />
    <rect x="2.5" y="0" width="7.5" height="1.6" fill="#000000" />
    <rect x="0.5" y="3.5" width="7" height="6" fill="none" stroke="#000000" />
    <rect x="0" y="3" width="8" height="1.6" fill="#000000" />
  </svg>
)

const CloseGlyph = () => (
  <svg viewBox="0 0 10 10" className={`w-[${px(9)}] h-[${px(9)}]`}>
    <path fill="none" stroke="#000000" strokeWidth="1.8" d="M1 1L9 9M9 1L1 9" />
  </svg>
)

const MinimizeGlyph = () => (
  <svg viewBox="0 0 10 10" className={`w-[${px(9)}] h-[${px(9)}]`}>
    <rect x="1" y="7.5" width="6" height="2" fill="#000000" />
  </svg>
)

// A window's title bar: the window in front's is blue, the others' gray.
const TitleBar = ({ title, active = true, maximized = false, onMinimize, onMaximize, onClose, ...drag }) => (
  <div
    className={`flex items-center h-[${px(24)}] gap-[${px(3)}] px-[${px(3)}] bg-gradient-to-r ${active ? 'from-[#000080] to-[#1084d0] text-white' : 'from-[#808080] to-[#b5b5b5] text-[#c0c0c0]'}`}
    {...drag}
  >
    <WindowIcon />
    <span className="flex-1 font-bold truncate">{title}</span>
    <TitleButton onClick={onMinimize}>
      <MinimizeGlyph />
    </TitleButton>
    <TitleButton onClick={onMaximize}>{maximized ? <RestoreGlyph /> : <MaximizeGlyph />}</TitleButton>
    <TitleButton onClick={onClose}>
      <CloseGlyph />
    </TitleButton>
  </div>
)

// A window's borders: four bevels, three pixels of gray inside them. `className`
// places it; `frame` are its own handlers (a press on the border sizes it).
const Frame = ({ className = '', frame = {}, children }) => (
  <div className={`flex flex-col bg-[#c0c0c0] border-t-${edge} border-l-${edge} border-[#dfdfdf] ${className}`} {...frame}>
    <div className={`flex flex-col flex-1 min-h-0 border-b-${edge} border-r-${edge} border-black`}>
      <div className={`flex flex-col flex-1 min-h-0 border-t-${edge} border-l-${edge} border-white`}>
        <div className={`flex flex-col flex-1 min-h-0 gap-[${px(2)}] p-[${px(2)}] border-b-${edge} border-r-${edge} border-[#808080]`}>
          {children}
        </div>
      </div>
    </div>
  </div>
)

// A window around the scene: its borders, and a title bar with the scene's name.
const Window = ({ title, onMinimize, onClose, children }) => (
  <Frame className="flex-1 min-h-0">
    <TitleBar title={title} onMinimize={onMinimize} onClose={onClose} />
    <div className="flex flex-col flex-1 min-h-0">{children}</div>
  </Frame>
)

// Four bars for the Wi-Fi signal, nothing on a frame that cannot tell.
function Signal({ rssi }) {
  if (typeof rssi !== 'number') return null
  const level = rssi >= -55 ? 4 : rssi >= -65 ? 3 : rssi >= -75 ? 2 : 1
  return (
    <div className={`flex items-end gap-[${px(2)}] h-[${px(15)}]`}>
      {[6, 9, 12, 15].map((height, i) => (
        <div className={`w-[${px(3)}] h-[${px(height)}] ${i < level ? 'bg-black' : 'bg-[#808080]'}`} />
      ))}
    </div>
  )
}

function Battery({ percent }) {
  if (typeof percent !== 'number') return null
  return (
    <svg viewBox="0 0 22 12" className={`w-[${px(22)}] h-[${px(12)}]`}>
      <rect x="0.5" y="0.5" width="18" height="11" fill="none" stroke="#000000" />
      <rect x="19" y="4" width="3" height="4" fill="#000000" />
      <rect x="2" y="2" width={(15 * percent) / 100} height="8" fill={percent > 15 ? '#000000' : '#800000'} />
    </svg>
  )
}

const Tray = ({ app, now }) => (
  <Sunken className="shrink-0 active:bg-[#909090]" onClick={() => frameos.dispatch('sceneSettings', { page: 'frame' })}>
    <Signal rssi={app.frame.wifiRssi} />
    <Battery percent={app.frame.batteryPercent} />
    <span className="whitespace-nowrap">{clock(now, on(app.state.twentyFourHour))}</span>
  </Sunken>
)

// The gray bar along the bottom: Start, what is open, the tray.
const Taskbar = ({ className = '', children }) => (
  <div className={`bg-[#c0c0c0] border-t-${edge} border-[#dfdfdf] ${className}`}>
    <div className={`flex items-stretch h-[${px(40)}] gap-[${px(4)}] p-[${px(3)}] border-t-${edge} border-white`}>{children}</div>
  </div>
)

// ---------------------------------------------------------------- the desktop
//
// What it keeps, in the layout's state (it goes along from scene to scene on a
// Pi, and is gone at a restart): `wins`, the windows open in the order they were
// opened, each {id, x, y, w, h, z, max, min}, in the desktop's pixels; `last`, the
// scene that had the focus at the last render; `gone`, the scene whose window was
// just closed; `full`, `menu`, `peek` and `drag`, a move or a size in progress.

const winsOf = (app) => (Array.isArray(app.state.wins) ? app.state.wins : [])
const topZ = (wins) => wins.reduce((z, w) => Math.max(z, w.z || 0), 0)

function clamp(win, deskW, deskH) {
  const minW = Math.min(deskW, Math.round(160 * zoom))
  const minH = Math.min(deskH, Math.round(100 * zoom))
  win.w = Math.round(Math.max(minW, Math.min(win.w, deskW)))
  win.h = Math.round(Math.max(minH, Math.min(win.h, deskH)))
  // A title bar stays where the pointer can get at it.
  const grip = Math.round(48 * zoom)
  win.x = Math.round(Math.max(grip - win.w, Math.min(win.x, deskW - grip)))
  win.y = Math.round(Math.max(0, Math.min(win.y, deskH - Math.round(24 * zoom))))
  return win
}

function placed(id, wins, deskW, deskH) {
  // The first window fills the desktop, which is what the frame looked like
  // before anything else was opened; the next ones cascade from the corner.
  const shown = wins.filter((w) => !w.min).length
  const step = Math.round(28 * zoom) * (wins.length % 6)
  const win = { id, x: Math.round(16 * zoom) + step, y: Math.round(16 * zoom) + step, w: deskW * 0.62, h: deskH * 0.62 }
  win.z = topZ(wins) + 1
  win.max = shown === 0
  return clamp(win, deskW, deskH)
}

function desktop(app, now, width, height) {
  const scale = app.frame.scale || 1
  const builtIn = app.frame.systemScene === true
  const current = app.frame.sceneId
  const names = {}
  for (const scene of app.frame.scenes) names[scene.id] = scene.name || scene.id
  if (!builtIn && current && !names[current]) names[current] = app.frame.sceneName || current
  const taskH = Math.round(40 * zoom) + 2 * edge
  const deskW = width
  const deskH = Math.max(1, height - taskH)

  // Whatever brought a scene forward (a window, Start, the scene list, a button,
  // the API), its window is open and on top, and the one it took the focus from
  // is next below it.
  const saved = winsOf(app)
  const wins = saved.filter((w) => w && names[w.id])
  let changed = wins.length !== saved.length
  if (!builtIn && current) {
    let win = wins.find((w) => w.id === current)
    if (!win && app.state.gone !== current) {
      win = placed(current, wins, deskW, deskH)
      wins.push(win)
      changed = true
    }
    if (app.state.last !== current) {
      if (win && win.min) win.min = false
      const before = wins.find((w) => w.id === app.state.last)
      if (before) before.z = topZ(wins) + 1
      if (app.state.gone && app.state.gone !== current) frameos.setState('gone', null)
      frameos.setState('last', current)
      changed = true
    }
  }
  if (changed) frameos.setState('wins', wins)

  const focused = builtIn ? null : wins.find((w) => w.id === current && !w.min)
  const full = !!focused && on(app.state.full)
  const controlPanel = builtIn && (app.frame.sceneName || '').includes('settings')
  const startMenu = on(app.state.menu)

  // What the handlers do. They read the state afresh: a drag's moves come
  // faster than renders.
  const update = (id, change) => {
    const next = winsOf(app).map((w) => (w.id === id ? { ...w, ...change(w) } : w))
    frameos.setState('wins', next)
  }
  const focus = (id) => {
    frameos.setState('menu', false)
    update(id, () => ({ min: false }))
    if (id !== current || builtIn) frameos.dispatch('setCurrentScene', { sceneId: id })
  }
  const open = (id) => {
    frameos.setState('menu', false)
    if (winsOf(app).some((w) => w.id === id)) return focus(id)
    if (id !== current) frameos.dispatch('setCurrentScene', { sceneId: id })
    else if (app.state.gone === id) frameos.setState('gone', null)
  }
  // The window in front went away: the next one down takes the focus.
  const nextAfter = (id) =>
    winsOf(app)
      .filter((w) => w.id !== id && !w.min)
      .sort((a, b) => (b.z || 0) - (a.z || 0))[0]
  const minimize = (id) => {
    update(id, () => ({ min: true }))
    const next = id === current ? nextAfter(id) : null
    if (next) frameos.dispatch('setCurrentScene', { sceneId: next.id })
  }
  const close = (id) => {
    const next = id === current ? nextAfter(id) : null
    frameos.setState('wins', winsOf(app).filter((w) => w.id !== id))
    if (id === current) {
      frameos.setState('gone', id)
      frameos.setState('full', false)
      if (next) frameos.dispatch('setCurrentScene', { sceneId: next.id })
    }
  }
  const toggleMax = (id) => update(id, (w) => ({ max: !w.max }))
  const toggleFull = () => {
    frameos.setState('menu', false)
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
  }

  // A press on a title bar moves the window, one on its border sizes it from
  // that edge; the moves that follow are captured by what was pressed.
  const startDrag = (win, mode) => (e) => {
    if (win.max) return focus(win.id)
    frameos.setState('drag', { id: win.id, mode, x: e.x, y: e.y, from: { x: win.x, y: win.y, w: win.w, h: win.h } })
    if (win.id !== current || builtIn) focus(win.id)
  }
  const dragTo = (e) => {
    const drag = app.state.drag
    if (!drag || !e.buttons) return
    const dx = (e.x - drag.x) / scale
    const dy = (e.y - drag.y) / scale
    const f = drag.from
    update(drag.id, () => {
      const box = { ...f }
      if (drag.mode === 'move') {
        box.x = f.x + dx
        box.y = f.y + dy
      } else {
        if (drag.mode.includes('l')) {
          box.x = Math.min(f.x + dx, f.x + f.w - 80 * zoom)
          box.w = f.w - (box.x - f.x)
        }
        if (drag.mode.includes('r')) box.w = f.w + dx
        if (drag.mode.includes('t')) {
          box.y = Math.max(0, Math.min(f.y + dy, f.y + f.h - 60 * zoom))
          box.h = f.h - (box.y - f.y)
        }
        if (drag.mode.includes('b')) box.h = f.h + dy
      }
      return clamp(box, deskW, deskH)
    })
  }
  const endDrag = () => frameos.setState('drag', null)
  const corner = 14 * zoom
  const edgeOf = (e) => {
    const x = e.localX < corner ? 'l' : e.localX > e.width - corner ? 'r' : ''
    const y = e.localY < corner ? 't' : e.localY > e.height - corner ? 'b' : ''
    return y + x || 'b'
  }
  const sizing = (win) => ({
    onPointerDown: (e) => startDrag(win, edgeOf(e))(e),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
  })
  const moving = (win) => ({
    onPointerDown: startDrag(win, 'move'),
    onPointerMove: dragTo,
    onPointerUp: endDrag,
    onDoubleClick: () => toggleMax(win.id),
  })

  const windowOf = (win) => {
    const active = win.id === current && !builtIn
    const box = win.max
      ? `left-0 top-0 w-[${deskW}px] h-[${deskH}px]`
      : `left-[${win.x}px] top-[${win.y}px] w-[${win.w}px] h-[${win.h}px]`
    return (
      <Frame className={`absolute ${box}`} frame={win.max ? {} : sizing(win)}>
        <TitleBar
          title={names[win.id]}
          active={active}
          maximized={win.max}
          onMinimize={() => minimize(win.id)}
          onMaximize={() => toggleMax(win.id)}
          onClose={() => close(win.id)}
          {...moving(win)}
        />
        <div className="relative flex flex-col flex-1 min-h-0">
          {active ? <yield /> : <Scene id={win.id} />}
          {/* A press on a window behind brings it forward, and is only that. */}
          {active ? null : <div className="absolute inset-0" onPointerDown={() => focus(win.id)} onClick={() => {}} />}
        </div>
      </Frame>
    )
  }

  if (full) {
    // The panel is the window's. The pointer at the bottom edge peeks at the
    // taskbar; moved back over the window, the taskbar goes again.
    const peek = on(app.state.peek)
    return (
      <div className="relative w-full h-full bg-[#008080] text-black">
        <div className="absolute inset-0 flex flex-col">
          <yield />
        </div>
        {peek ? (
          <div className={`absolute left-0 top-0 w-full h-[${deskH}px]`} onPointerMove={() => frameos.setState('peek', false)} />
        ) : (
          <div className="absolute left-0 bottom-0 w-full h-[2px]" onPointerMove={() => frameos.setState('peek', true)} />
        )}
        {peek ? bar() : null}
      </div>
    )
  }

  const shown = wins.filter((w) => !w.min && !(focused && w.id === focused.id)).sort((a, b) => (a.z || 0) - (b.z || 0))
  if (focused) shown.push(focused)
  return (
    <div className={`relative flex flex-col w-full h-full bg-[#008080] text-black text-[${px(16)}]`}>
      <div className="relative flex-1 min-h-0">
        {shown.map(windowOf)}
        {builtIn ? (
          <div className="absolute inset-0 flex flex-col">
            <Window title={controlPanel ? 'Control Panel' : 'Programs'} onMinimize={closeBuiltIn} onClose={closeBuiltIn}>
              <yield />
            </Window>
          </div>
        ) : null}
      </div>
      {startMenu ? <div className="absolute inset-0" onPointerDown={() => frameos.setState('menu', false)} onClick={() => {}} /> : null}
      {startMenu ? menu() : null}
      {bar()}
    </div>
  )

  function closeBuiltIn() {
    frameos.dispatch(controlPanel ? 'sceneSettings' : 'sceneSwitcher')
  }

  function bar() {
    const taskW = Math.round(Math.min(160 * zoom, Math.max(48 * zoom, (width - 220 * zoom) / Math.max(1, wins.length))))
    return (
      <Taskbar className={full ? 'absolute left-0 bottom-0 w-full' : ''}>
        <Toggle pressed={startMenu} className="shrink-0" onClick={() => frameos.setState('menu', !startMenu)}>
          <Logo />
          <span className="font-bold whitespace-nowrap">Start</span>
        </Toggle>
        <div className={`flex flex-1 min-w-0 gap-[${px(4)}]`}>
          {wins.map((win) => {
            const front = !builtIn && win.id === current && !win.min
            return (
              <Toggle
                pressed={front}
                className={`w-[${taskW}px] min-w-0`}
                onClick={() => (front ? minimize(win.id) : focus(win.id))}
              >
                <WindowIcon />
                <span className="flex-1 font-bold truncate">{names[win.id]}</span>
              </Toggle>
            )
          })}
        </div>
        <Tray app={app} now={now} />
      </Taskbar>
    )
  }

  function menu() {
    const Item = ({ onClick, children }) => (
      <div className={`flex items-center gap-[${px(8)}] h-[${px(30)}] px-[${px(8)}] hover:bg-[#000080] hover:text-white`} onClick={onClick}>
        {children}
      </div>
    )
    const Rule = () => (
      <div className={`flex flex-col py-[${px(3)}]`}>
        <div className={`h-[${edge}px] bg-[#808080]`} />
        <div className={`h-[${edge}px] bg-white`} />
      </div>
    )
    const menuW = Math.round(Math.min(width - 8 * zoom, 240 * zoom))
    const menuH = Math.round(Math.min(deskH - 8 * zoom, (30 * (app.frame.scenes.length + 3) + 22) * zoom))
    return (
      <Frame className={`absolute left-[${px(2)}] bottom-[${taskH - edge}px] w-[${menuW}px] h-[${menuH}px]`}>
        <div className="flex flex-1 min-h-0">
          <div className={`flex flex-col justify-end w-[${px(24)}] bg-gradient-to-b from-[#000080] to-[#1084d0] text-white font-bold text-[${px(13)}]`}>
            <span className={`px-[${px(4)}] pb-[${px(6)}]`}>98</span>
          </div>
          <div className="flex flex-col flex-1 min-w-0">
            <div className="flex flex-col flex-1 min-h-0 overflow-y-auto">
              {app.frame.scenes.map((scene) => (
                <Item onClick={() => open(scene.id)}>
                  <WindowIcon />
                  <span className="flex-1 truncate">{scene.name || scene.id}</span>
                </Item>
              ))}
            </div>
            <Rule />
            <Item onClick={toggleFull}>
              <MaximizeGlyph />
              <span className="flex-1 truncate">Full screen</span>
            </Item>
            <Item onClick={() => (frameos.setState('menu', false), frameos.dispatch('sceneSettings'))}>
              <Gear />
              <span className="flex-1 truncate">Scene settings</span>
            </Item>
            <Item onClick={() => (frameos.setState('menu', false), frameos.dispatch('sceneSettings', { page: 'frame' }))}>
              <Gear />
              <span className="flex-1 truncate">Control Panel</span>
            </Item>
          </div>
        </div>
      </Frame>
    )
  }
}

// F11 gives the panel to the window in front and takes it back; Escape closes
// Start and leaves the full screen. The scene heard the key first.
export function onEvent(app, context) {
  if (context.event !== 'keyDown' || !Array.isArray(app.frame.scenes) || !windowsOn(app)) return false
  const key = context.payload && context.payload.key
  if (key === 'F11') {
    frameos.setState('peek', false)
    frameos.setState('full', !on(app.state.full))
    return true
  }
  if (key === 'Escape' && (on(app.state.menu) || on(app.state.full))) {
    frameos.setState('menu', false)
    frameos.setState('full', false)
    return true
  }
  return false
}

const windowsOn = (app) => app.state.windows !== false && app.state.windows !== 'false'

export function get(app) {
  // app.frame's size is the panel's over the render scale, before the frame's rotation.
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = turned ? app.frame.height : app.frame.width
  const height = turned ? app.frame.width : app.frame.height
  const shortSide = Math.min(app.frame.width, app.frame.height) * (app.frame.scale || 1)
  zoom = shortSide >= 1000 ? 2 : shortSide >= 480 ? 1 : shortSide / 480
  edge = Math.max(1, Math.round(zoom))
  const now = new Date()
  // The clock changes on the minute: nothing to draw until then.
  frameos.setNextSleep(60 - now.getSeconds())
  if (Array.isArray(app.frame.scenes) && windowsOn(app)) return desktop(app, now, width, height)
  // The words beside the gear need room: nothing else gives way for them.
  const roomy = width >= 640 * Math.max(zoom, 1)
  const name = app.frame.sceneName || 'FrameOS'
  const builtIn = app.frame.systemScene === true
  const controlPanel = builtIn && name.includes('settings')
  const startMenu = builtIn && !controlPanel
  // The window a built-in scene opened over: its task button stays.
  const openWindow = builtIn ? app.state.openedOver : name
  const title = controlPanel ? 'Control Panel' : startMenu ? 'Programs' : name
  const minimized = !builtIn && app.state.minimized === true
  const toggle = () => frameos.setState('minimized', !minimized)
  // A built-in scene's own command, again, goes back to the scene it opened over.
  const closeBuiltIn = () => frameos.dispatch(controlPanel ? 'sceneSettings' : 'sceneSwitcher')
  const taskWidth = Math.round(Math.min(160 * zoom, width * 0.34))
  return (
    <div className={`flex flex-col w-full h-full bg-[#008080] text-black text-[${px(16)}]`}>
      {minimized ? (
        <div className="flex-1" />
      ) : on(app.state.showWindowBar) ? (
        <Window
          title={title}
          onMinimize={builtIn ? closeBuiltIn : toggle}
          onClose={builtIn ? closeBuiltIn : () => frameos.dispatch('sceneSwitcher')}
        >
          <yield />
        </Window>
      ) : (
        <yield />
      )}
      <Taskbar>
        <Toggle pressed={startMenu} className="shrink-0" onClick={() => frameos.dispatch('sceneSwitcher', { swap: true })}>
          <Logo />
          <span className="font-bold whitespace-nowrap">Start</span>
        </Toggle>
        {openWindow ? (
          <Toggle
            pressed={!builtIn && !minimized}
            className={`w-[${taskWidth}px] min-w-0`}
            onClick={builtIn ? closeBuiltIn : toggle}
          >
            <WindowIcon />
            <span className="flex-1 font-bold truncate">{openWindow}</span>
          </Toggle>
        ) : null}
        <Toggle pressed={controlPanel} className="shrink-0" onClick={() => frameos.dispatch('sceneSettings')}>
          <Gear />
          {roomy ? <span className="whitespace-nowrap">Control Panel</span> : null}
        </Toggle>
        <div className="flex-1" />
        <Tray app={app} now={now} />
      </Taskbar>
    </div>
  )
}
